// Cloudflare Worker: maintenance-page
//
// Bound to app.gamefolio.com/* routes. Reserved VM deployments run on a
// single dedicated machine, so a new publish has to stop the old process
// before the new one can build and boot — there's no second instance to
// keep serving traffic in the meantime (unlike Autoscale, which can spin up
// fresh instances alongside old ones). That gap shows up as a raw
// "Internal Server Error" for several minutes on every deploy.
//
// This Worker catches that gap at the edge: if the origin is unreachable or
// returns a 5xx, top-level page navigations get a self-contained "back
// soon" page (own embedded image, no external asset dependencies, since the
// origin serving those assets is exactly what's down) instead of the raw
// error. API requests get a small JSON 503 instead of HTML, so the native
// app's existing error handling (which expects JSON) doesn't choke on it.
// Everything else — healthy responses, static assets, non-5xx errors —
// passes through untouched.

const MASCOT_WEBP_BASE64 =
  "";

const MASCOT_DATA_URI = "data:image/webp;base64," + MASCOT_WEBP_BASE64;

const MAINTENANCE_HTML = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<meta http-equiv="refresh" content="15" />
<title>Gamefolio — Back in a moment</title>
<meta name="robots" content="noindex" />
<style>
  html, body {
    margin: 0;
    padding: 0;
    height: 100%;
    background: radial-gradient(circle at 50% 30%, #16240f 0%, #0a0e0a 65%, #050705 100%);
    color: #e2e8f0;
    font-family: 'Space Grotesk', 'Inter', system-ui, sans-serif;
  }
  .wrap {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 48px 24px;
    box-sizing: border-box;
  }
  img {
    width: 100%;
    max-width: 320px;
    height: auto;
    margin-bottom: 8px;
    filter: drop-shadow(0 0 40px rgba(183, 255, 26, 0.25));
  }
  h1 {
    font-size: 30px;
    line-height: 1.2;
    margin: 0 0 16px 0;
    font-weight: 700;
    color: #B7FF1A;
  }
  p {
    font-size: 17px;
    color: #cbd5e1;
    max-width: 480px;
    margin: 0;
    line-height: 1.6;
  }
  .brand {
    margin-top: 40px;
    font-size: 14px;
    color: #64748b;
    letter-spacing: 0.05em;
  }
</style>
</head>
<body>
  <div class="wrap">
    <img src="${MASCOT_DATA_URI}" alt="Gamefolio maintenance" width="320" height="480" />
    <h1>We'll be right back</h1>
    <p>Gamefolio is currently undergoing scheduled maintenance while we roll out an update. We'll be back online in just a few minutes — thanks for your patience.</p>
    <div class="brand">GAMEFOLIO</div>
  </div>
</body>
</html>`;

function maintenancePage() {
  return new Response(MAINTENANCE_HTML, {
    status: 503,
    headers: {
      "content-type": "text/html; charset=UTF-8",
      "cache-control": "no-store",
      "retry-after": "30",
    },
  });
}

function apiUnavailable() {
  return new Response(
    JSON.stringify({
      message:
        "Gamefolio is temporarily unavailable — we're rolling out an update. Please try again in a few minutes.",
    }),
    {
      status: 503,
      headers: {
        "content-type": "application/json",
        "cache-control": "no-store",
        "retry-after": "30",
      },
    }
  );
}

// True only for a top-level browser navigation to an HTML document — not
// API/XHR calls, not JS/CSS/image/font requests. Sec-Fetch-Dest is sent by
// all modern browsers; the Accept-header check is the fallback for the rare
// client that omits it.
function isDocumentRequest(request) {
  const dest = request.headers.get("sec-fetch-dest");
  if (dest) return dest === "document";
  const accept = request.headers.get("accept") || "";
  return accept.includes("text/html");
}

function isApiPath(pathname) {
  return (
    pathname.startsWith("/api/") ||
    pathname.startsWith("/oauth/") ||
    pathname.startsWith("/.well-known/")
  );
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const api = isApiPath(url.pathname);

    let response;
    try {
      response = await fetch(request);
    } catch (err) {
      // Origin totally unreachable — the exact mid-deploy stop/start gap.
      if (api) return apiUnavailable();
      if (isDocumentRequest(request)) return maintenancePage();
      return new Response("Service unavailable", {
        status: 503,
        headers: { "cache-control": "no-store", "retry-after": "30" },
      });
    }

    if (response.status >= 500 && response.status <= 599) {
      if (api) return apiUnavailable();
      if (isDocumentRequest(request)) return maintenancePage();
    }

    return response;
  },
};
